    @Test void exchangeRefundConversionAndActualDispatchSerializeBothCanonicalParentWaitOrders() throws Exception {
        for(boolean conversionFirst:List.of(true,false)) {
            var f=pendingActualExchange(conversionFirst?"e-frc":"e-frd");var buyer=f.parties().buyer();var id=f.accepted().exchangeId();var authority=shipmentAuthority(buyer);var api=context.getBean(com.example.marketplace.claim.api.ExchangeRefunds.class);var quote=api.quote(buyer.order().orderNumber(),id,authority,4).quote();var command=new com.example.marketplace.claim.api.ExchangeRefunds.Consent("conversion-race",4L,quote.id(),quote.fingerprint(),true,quote.legacyConsentRequired(),"explicit buyer conversion competes with actual reserved-stock dispatch");var actual=claimActualExchangeJob(f.jobId(),Instant.now().plusSeconds(1));var worker=exchangeDispatcherWith(actual.jobs());
            java.util.concurrent.Callable<String> conversion=()->{try{api.consent(buyer.order().orderNumber(),id,authority,command);return "CONVERTED";}catch(com.example.marketplace.order.api.OrderRejected rejected){assertEquals(409,rejected.status());return "DENIED";}};
            java.util.concurrent.Callable<String> dispatch=()->{try{assertEquals(com.example.marketplace.platform.api.JobHandler.Result.COMPLETE,worker.dispatch(actual.job()));return jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_dispatch_effect WHERE exchange_id=:id",Map.of("id",id),Integer.class)==1?"DISPATCHED":"NO_EFFECT";}catch(com.example.marketplace.order.api.OrderRejected rejected){assertEquals(409,rejected.status());return "DENIED";}};
            String firstResult,secondResult;
            try(var pool=Executors.newFixedThreadPool(2);var blocker=context.getBean(DataSource.class).getConnection()) {
                blocker.setAutoCommit(false);int pid;try(var statement=blocker.createStatement();var result=statement.executeQuery("SELECT pg_backend_pid()")){assertTrue(result.next());pid=result.getInt(1);}try(var lock=blocker.prepareStatement("SELECT id FROM marketplace.purchase_order WHERE id=? FOR UPDATE")){lock.setObject(1,buyer.order().id());lock.executeQuery().close();}
                var first=pool.submit(conversionFirst?conversion:dispatch);exchangeRefundAwaitParentChain(pid,1,List.of(first),"e-refund-race-first-"+conversionFirst);var second=pool.submit(conversionFirst?dispatch:conversion);exchangeRefundAwaitParentChain(pid,2,List.of(first,second),"e-refund-race-both-"+conversionFirst);assertFalse(first.isDone());assertFalse(second.isDone());blocker.commit();firstResult=first.get(10,TimeUnit.SECONDS);secondResult=second.get(10,TimeUnit.SECONDS);
            }
            assertEquals(conversionFirst?"CONVERTED":"DISPATCHED",firstResult);assertTrue(List.of("DENIED","NO_EFFECT").contains(secondResult));assertEquals(conversionFirst?1:0,jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_refund_consent WHERE exchange_id=:id",Map.of("id",id),Integer.class));assertEquals(conversionFirst?0:1,jdbc.queryForObject("SELECT count(*) FROM marketplace.fulfillment_exchange_shipment WHERE exchange_id=:id",Map.of("id",id),Integer.class));assertEquals(conversionFirst?0:1,jdbc.queryForObject("SELECT count(*) FROM marketplace.inventory_exchange_commit WHERE reservation_id IN(SELECT id FROM marketplace.inventory_exchange_reservation WHERE exchange_id=:id)",Map.of("id",id),Integer.class));assertEquals(conversionFirst?1:0,jdbc.queryForObject("SELECT count(*) FROM marketplace.inventory_exchange_release WHERE exchange_id=:id AND reason='REFUND_CONVERSION'",Map.of("id",id),Integer.class));
            var before=exchangeRefundParticipants();assertEquals(com.example.marketplace.platform.api.JobHandler.Result.COMPLETE,worker.dispatch(actual.job()));assertEquals(before,exchangeRefundParticipants(),"winner's existing exact dispatch job replay creates no new reservation, shipment, refund or receipt");assertTrue(actual.jobs().complete(actual.job().id(),actual.job().ownerToken()));java.nio.file.Files.writeString(java.nio.file.Path.of(System.getenv("A3_EVIDENCE"),"e-refund-race-results-"+conversionFirst+".json"),authMapper.writeValueAsString(Map.of("conversionFirst",conversionFirst,"first",firstResult,"second",secondResult,"differentBuyerSeller",!authority.member().equals(shipmentAuthority(f.parties().seller()).member()),"allFinancialAndStockParticipants",exchangeRefundParticipants())));
        }
    }

    @Test void exchangeRefundConsentReadyAndCompletionSqlFailuresRollBackEveryFinancialParticipant() throws Exception {
        var f=pendingActualExchange("e-fsql");var buyer=f.parties().buyer();var id=f.accepted().exchangeId();var api=context.getBean(com.example.marketplace.claim.api.ExchangeRefunds.class);var quote=api.quote(buyer.order().orderNumber(),id,shipmentAuthority(buyer),4).quote();var command=new com.example.marketplace.claim.api.ExchangeRefunds.Consent("sql-consent",4L,quote.id(),quote.fingerprint(),true,quote.legacyConsentRequired(),"actual complete financial transaction rollback");var before=exchangeRefundParticipants();
        for(String table:List.of("inventory_exchange_release_unit","claim_exchange_command","claim_exchange_refund_consent")){exchangeRefundAssertSqlFailure(table,table,"",before,()->api.consent(buyer.order().orderNumber(),id,shipmentAuthority(buyer),command));}
        var accepted=api.consent(buyer.order().orderNumber(),id,shipmentAuthority(buyer),command);runCancellationJob("REFUND_SUBMIT.v1",accepted.refundAttemptId());runCancellationJob("REFUND_RESULT_RECORDED.v1",accepted.refundAttemptId());UUID readyJob=jdbc.queryForObject("SELECT id FROM marketplace.job WHERE type='EXCHANGE_REFUND_RESUME.v1' AND cause_key=:id AND status='READY'",Map.of("id",id.toString()),UUID.class);var owned=claimActualExchangeJob(readyJob,Instant.now().plusSeconds(1));var worker=context.getBean(com.example.marketplace.claim.infrastructure.ExchangeRefundFinancialWorker.class);before=exchangeRefundParticipants();
        for(String table:List.of("claim_fee_application","claim_exchange_refund_effect","claim_exchange_refund_item_ready","claim_exchange_refund_ready_unit")){var stable=before;exchangeRefundAssertSqlFailure(table,table,"",stable,()->worker.resume(owned.job()));}
        assertEquals(com.example.marketplace.platform.api.JobHandler.Result.COMPLETE,worker.resume(owned.job()));assertTrue(owned.jobs().complete(readyJob,owned.job().ownerToken()));UUID completeJob=jdbc.queryForObject("SELECT id FROM marketplace.job WHERE type='SELLER_AFTERCARE_REEVALUATE.v1' AND cause_key=:id AND status='READY'",Map.of("id",buyer.order().sellers().getFirst().id().toString()),UUID.class);var completing=claimActualExchangeJob(completeJob,Instant.now().plusSeconds(1));var completion=context.getBean(com.example.marketplace.claim.infrastructure.SellerAftercareWorker.class);before=exchangeRefundParticipants();
        for(String table:List.of("order_exchange_refund_completion","order_exchange_refund_completion_unit","claim_exchange_refund_completion","order_aftercare_closure")){var stable=before;exchangeRefundAssertSqlFailure(table,table,"",stable,()->completion.reevaluate(completing.job()));}
        assertEquals(com.example.marketplace.platform.api.JobHandler.Result.COMPLETE,completion.reevaluate(completing.job()));var committed=exchangeRefundParticipants();assertEquals(com.example.marketplace.platform.api.JobHandler.Result.COMPLETE,completion.reevaluate(completing.job()));assertEquals(committed,exchangeRefundParticipants());assertTrue(completing.jobs().complete(completeJob,completing.job().ownerToken()));assertEquals("CLOSED",orders().find(buyer.order().orderNumber()).state());
    }

